function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

	// var ga2 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
	// ga2.addParam('sysparm_name', 'displayTransRef');
