    //     var res = JSON.parse(response);      
    //     g_form.setValue('transaction_reference', res);
	// 	g_form.save();
    // });

    var ga1 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
    ga1.addParam('sysparm_name', 'getPairTradeDetails');
	ga1.addParam('sysparm_transaction_reference', newValue);
    //ga1.addParam('sysparm_sys_id', g_form.getUniqueValue());

	ga1.getXMLAnswer(function(response) {
        var res = JSON.parse(response);

        g_form.setValue('transaction_type_display', res.transactionTypeDisp);
		g_form.setValue('legacy_status_display', res.legacyTypeDisp);
    });

